import { QuizQuestion } from '../types';

/**
 * Extended Science & Nature bank (189 new questions, ids 434-622).
 * Together with the deduped original questions this gives 225 unique
 * Science & Nature questions for the 90-day no-repeat schedule.
 */
export const SCIENCE_QUIZ_QUESTIONS: QuizQuestion[] = [
  { id: 434, category: 'Science and Nature', question: 'What is the chemical symbol for carbon?', options: ['C', 'Ca', 'Co', 'Cr'], correctIndex: 0, explanation: 'Carbon, the backbone of all known life, is simply C on the periodic table.' },
  { id: 435, category: 'Science and Nature', question: 'What is the chemical symbol for oxygen?', options: ['O', 'Ox', 'Og', 'Oh'], correctIndex: 0, explanation: 'Oxygen is O; Og is actually oganesson, element 118.' },
  { id: 436, category: 'Science and Nature', question: 'What is the chemical symbol for iron?', options: ['Ir', 'Fe', 'In', 'Io'], correctIndex: 1, explanation: 'Fe comes from ferrum, the Latin word for iron.' },
  { id: 437, category: 'Science and Nature', question: 'What is the chemical symbol for sodium?', options: ['So', 'Na', 'Sd', 'Nt'], correctIndex: 1, explanation: 'Na comes from natrium, the Latin name for sodium.' },
  { id: 438, category: 'Science and Nature', question: 'What is the chemical symbol for calcium?', options: ['Ct', 'Cd', 'Ca', 'Cn'], correctIndex: 2, explanation: 'Calcium is Ca; Cd is cadmium, a toxic heavy metal.' },
  { id: 439, category: 'Science and Nature', question: 'What is the chemical symbol for nitrogen?', options: ['Ni', 'N', 'No', 'Nb'], correctIndex: 1, explanation: 'Nitrogen is N; Ni is nickel.' },
  { id: 440, category: 'Science and Nature', question: 'Which planet is the closest to the Sun?', options: ['Venus', 'Mercury', 'Mars', 'Earth'], correctIndex: 1, explanation: 'Mercury orbits the Sun every 88 Earth days.' },
  { id: 441, category: 'Science and Nature', question: 'Which is the largest planet in our solar system?', options: ['Saturn', 'Jupiter', 'Neptune', 'Earth'], correctIndex: 1, explanation: 'Jupiter is so big that over 1,300 Earths could fit inside it.' },
  { id: 442, category: 'Science and Nature', question: 'Which planet is the hottest in our solar system?', options: ['Mercury', 'Venus', 'Mars', 'Jupiter'], correctIndex: 1, explanation: 'Venus\'s thick CO2 atmosphere traps heat, keeping it around 465 C - hotter than Mercury.' },
  { id: 443, category: 'Science and Nature', question: 'Which planet is known for its thick, bright ring system made of ice and rock?', options: ['Jupiter', 'Neptune', 'Saturn', 'Uranus'], correctIndex: 2, explanation: 'Saturn\'s rings span 280,000 km but are only about 10 m thick in places.' },
  { id: 444, category: 'Science and Nature', question: 'Titan, the largest moon of Saturn, is notable for having what?', options: ['A dense atmosphere', 'Lava lakes', 'Oxygen air', 'Liquid methane clouds and lakes'], correctIndex: 3, explanation: 'Titan has rivers and seas of liquid methane - the only other world with stable surface liquids besides Earth.' },
  { id: 445, category: 'Science and Nature', question: 'Europa, a moon of Jupiter, is thought to hide what beneath its icy shell?', options: ['A global salt-water ocean', 'Iron core only', 'Magma only', 'A diamond layer'], correctIndex: 0, explanation: 'Tidal flexing from Jupiter keeps a global ocean liquid under Europa\'s ice - a prime target in the search for life.' },
  { id: 446, category: 'Science and Nature', question: 'Which was reclassified from a planet to a "dwarf planet" in 2006?', options: ['Pluto', 'Ceres', 'Eris', 'Both Pluto and others'], correctIndex: 0, explanation: 'The IAU\'s 2006 definition demoted Pluto because it cannot "clear its orbital neighbourhood".' },
  { id: 447, category: 'Science and Nature', question: 'Ceres, the largest object in the asteroid belt, is classified as what?', options: ['A dwarf planet', 'A comet', 'A moon', 'A gas giant'], correctIndex: 0, explanation: 'Ceres is the only dwarf planet in the inner solar system, between Mars and Jupiter.' },
  { id: 448, category: 'Science and Nature', question: 'Comets develop their glowing tails mainly when they get close to what?', options: ['The Moon', 'The Sun', 'Other comets', 'Earth'], correctIndex: 1, explanation: 'Solar heat vaporises ices in the comet nucleus, and the solar wind blows the gas and dust into a tail.' },
  { id: 449, category: 'Science and Nature', question: 'The Andromeda Galaxy, the nearest large galaxy to the Milky Way, is about how far away?', options: ['100,000 light-years', '2.5 million light-years', '100 million light-years', '1 billion light-years'], correctIndex: 1, explanation: 'Andromeda is around 2.5 million light-years away and is slowly drifting toward us.' },
  { id: 450, category: 'Science and Nature', question: 'What type of object is a black hole best described as?', options: ['A region where gravity is so strong that not even light can escape', 'A dark planet', 'A cold star', 'A huge moon'], correctIndex: 0, explanation: 'Inside a black hole\'s event horizon, escape velocity exceeds the speed of light.' },
  { id: 451, category: 'Science and Nature', question: 'A "light-year" is a measure of what?', options: ['Distance', 'Time', 'Brightness', 'Speed'], correctIndex: 0, explanation: 'A light-year is the distance light travels in a year - about 9.46 trillion km.' },
  { id: 452, category: 'Science and Nature', question: 'How long does sunlight take to reach Earth?', options: ['8 seconds', '8 minutes', '8 hours', '8 days'], correctIndex: 1, explanation: 'Sunlight is about 8 minutes 20 seconds old by the time it hits your face.' },
  { id: 453, category: 'Science and Nature', question: 'Which is the largest internal organ of the human body?', options: ['Liver', 'Heart', 'Lungs', 'Brain'], correctIndex: 0, explanation: 'The liver, about 1.5 kg, performs over 500 jobs including detox and bile production.' },
  { id: 454, category: 'Science and Nature', question: 'Which is the longest organ in the human body?', options: ['Large intestine', 'Small intestine', 'Trachea', 'Oesophagus'], correctIndex: 1, explanation: 'The small intestine is around 6-7 m long when unrolled.' },
  { id: 455, category: 'Science and Nature', question: 'Which blood cells are responsible for clotting?', options: ['Red blood cells', 'White blood cells', 'Platelets', 'Plasma cells'], correctIndex: 2, explanation: 'Platelets clump at wounds to form the first stopgap of a clot.' },
  { id: 456, category: 'Science and Nature', question: 'Which protein in red blood cells carries oxygen around the body?', options: ['Keratin', 'Collagen', 'Haemoglobin', 'Insulin'], correctIndex: 2, explanation: 'Haemoglobin\'s iron atoms each grab an oxygen molecule in the lungs.' },
  { id: 457, category: 'Science and Nature', question: 'Which is the largest artery in the human body?', options: ['Aorta', 'Carotid', 'Femoral', 'Pulmonary artery'], correctIndex: 0, explanation: 'The aorta is about the width of a hockey stick and carries blood from the heart.' },
  { id: 458, category: 'Science and Nature', question: 'Which is the longest and strongest bone in the human body?', options: ['Tibia', 'Femur', 'Spine', 'Humerus'], correctIndex: 1, explanation: 'The femur (thigh bone) is longer than any other bone and bears most of your weight.' },
  { id: 459, category: 'Science and Nature', question: 'Which muscle, shaped like a dome, is the main driver of breathing?', options: ['Biceps', 'Diaphragm', 'Quadriceps', 'Pectorals'], correctIndex: 1, explanation: 'The diaphragm flattens on each breath, pulling air into the lungs.' },
  { id: 460, category: 'Science and Nature', question: 'Which part of the eye converts light into nerve signals?', options: ['Cornea', 'Retina', 'Lens', 'Iris'], correctIndex: 1, explanation: 'The retina\'s photoreceptor cells - rods and cones - turn light into electrical signals.' },
  { id: 461, category: 'Science and Nature', question: 'Which spiral-shaped structure in the inner ear is responsible for hearing?', options: ['Semicircular canals', 'Cochlea', 'Eustachian tube', 'Uvula'], correctIndex: 1, explanation: 'The cochlea\'s fluid and hair cells translate sound vibrations into nerve impulses.' },
  { id: 462, category: 'Science and Nature', question: 'Which nerve carries visual information from the eye to the brain?', options: ['Vagus nerve', 'Optic nerve', 'Facial nerve', 'Sciatic nerve'], correctIndex: 1, explanation: 'The optic nerve carries about a million fibres from each eye to the brain.' },
  { id: 463, category: 'Science and Nature', question: 'Which part of the brain coordinates balance and movement?', options: ['Cerebrum', 'Cerebellum', 'Hypothalamus', 'Thalamus'], correctIndex: 1, explanation: 'The cerebellum, "little brain", fine-tunes smooth, coordinated motion.' },
  { id: 464, category: 'Science and Nature', question: 'Which hormone, released in darkness, helps regulate sleep?', options: ['Cortisol', 'Melatonin', 'Adrenaline', 'Thyroxine'], correctIndex: 1, explanation: 'Melatonin rises as light fades - bright screens in bed can suppress it.' },
  { id: 465, category: 'Science and Nature', question: 'How many bones are in the adult human skeleton?', options: ['206', '186', '226', '156'], correctIndex: 0, explanation: 'Babies are born with about 300; many fuse together as we grow to reach 206.' },
  { id: 466, category: 'Science and Nature', question: 'Which cells of the immune system primarily fight infection?', options: ['Red blood cells', 'White blood cells', 'Platelets', 'Skin cells'], correctIndex: 1, explanation: 'White blood cells (leukocytes) hunt and destroy invaders like bacteria and viruses.' },
  { id: 467, category: 'Science and Nature', question: 'Which gland in the neck helps regulate metabolism?', options: ['Thyroid', 'Pituitary', 'Adrenal', 'Pancreas'], correctIndex: 0, explanation: 'Thyroid hormones control how fast the body uses energy.' },
  { id: 468, category: 'Science and Nature', question: 'The adrenal glands, which release adrenaline, sit on top of which organs?', options: ['The kidneys', 'The lungs', 'The heart', 'The liver'], correctIndex: 0, explanation: 'Each adrenal gland caps one kidney and triggers the "fight or flight" response.' },
  { id: 469, category: 'Science and Nature', question: 'Which tube carries food from the throat to the stomach?', options: ['Trachea', 'Oesophagus', 'Ureter', 'Fallopian tube'], correctIndex: 1, explanation: 'The oesophagus squeezes food down with wave-like contractions called peristalsis.' },
  { id: 470, category: 'Science and Nature', question: 'Which part of the digestive system absorbs most of the water from waste?', options: ['Stomach', 'Small intestine', 'Large intestine', 'Mouth'], correctIndex: 2, explanation: 'The large intestine reclaims water, turning liquid waste into faeces.' },
  { id: 471, category: 'Science and Nature', question: 'Which organ produces both digestive enzymes and the hormone insulin?', options: ['Liver', 'Stomach', 'Pancreas', 'Gallbladder'], correctIndex: 2, explanation: 'The pancreas has a double job: digesting food and controlling blood sugar.' },
  { id: 472, category: 'Science and Nature', question: 'Which small sac stores bile before it is released into the intestine?', options: ['Spleen', 'Gallbladder', 'Appendix', 'Bladder'], correctIndex: 1, explanation: 'The gallbladder keeps bile - made by the liver - ready for fat digestion.' },
  { id: 473, category: 'Science and Nature', question: 'Which transparent front "window" of the eye focuses incoming light?', options: ['Cornea', 'Retina', 'Sclera', 'Vitreous humor'], correctIndex: 0, explanation: 'The cornea provides most of the eye\'s focusing power.' },
  { id: 474, category: 'Science and Nature', question: 'The small flap of tissue at the back of the mouth, that can be felt with a "ahh", is called what?', options: ['Uvula', 'Tonsil', 'Epiglottis', 'Septum'], correctIndex: 0, explanation: 'The uvula helps direct food away from the airway and shapes speech sounds.' },
  { id: 475, category: 'Science and Nature', question: 'In which chamber pair does blood enter the heart from the body?', options: ['Ventricles', 'Atria', 'Capillaries', 'Aorta'], correctIndex: 1, explanation: 'The two upper chambers (atria) receive blood; the ventricles pump it out.' },
  { id: 476, category: 'Science and Nature', question: 'DNA, the molecule that carries genetic information, is shaped like what?', options: ['A single strand', 'A double helix', 'A flat sheet', 'A spiral staircase of protein'], correctIndex: 1, explanation: 'Watson and Crick described DNA\'s double-helix structure in 1953.' },
  { id: 477, category: 'Science and Nature', question: 'How many pairs of chromosomes do humans have?', options: ['23', '46', '21', '25'], correctIndex: 0, explanation: 'We have 46 chromosomes in 23 pairs; the last pair (XX or XY) determines sex.' },
  { id: 478, category: 'Science and Nature', question: 'Which sex is determined by having one X and one Y chromosome?', options: ['Female', 'Male', 'Neither', 'Both'], correctIndex: 1, explanation: 'XX is female, XY is male in humans.' },
  { id: 479, category: 'Science and Nature', question: 'Identical twins share the same DNA because they develop from what?', options: ['Two separate eggs', 'One fertilised egg that splits', 'Two sperm', 'One egg and no sperm'], correctIndex: 1, explanation: 'A single zygote splits into two embryos, giving genetically identical twins.' },
  { id: 480, category: 'Science and Nature', question: 'The theory of evolution by natural selection was proposed by which scientist?', options: ['Gregor Mendel', 'Charles Darwin', 'Isaac Newton', 'Louis Pasteur'], correctIndex: 1, explanation: 'Darwin set out natural selection in "On the Origin of Species" (1859).' },
  { id: 481, category: 'Science and Nature', question: 'In biology, a "species" is a group of organisms that can what?', options: ['Live in the same habitat', 'Breed together and produce fertile offspring', 'Eat the same food', 'Look identical'], correctIndex: 1, explanation: 'The ability to interbreed is the classic definition of a species.' },
  { id: 482, category: 'Science and Nature', question: 'Reptiles, such as lizards and snakes, are best described as what kind of animals?', options: ['Warm-blooded', 'Cold-blooded', 'Mammals', 'Amphibians'], correctIndex: 1, explanation: 'Reptiles rely on their surroundings to regulate body temperature.' },
  { id: 483, category: 'Science and Nature', question: 'The platypus, a strange Australian animal, is a mammal that does what unusual thing?', options: ['Lays eggs', 'Flies', 'Lives in trees only', 'Is warm to the touch only'], correctIndex: 0, explanation: 'Platypuses (and echidnas) are monotremes - egg-laying mammals.' },
  { id: 484, category: 'Science and Nature', question: 'A starfish belongs to which group of animals?', options: ['Fish', 'Echinoderms (spiny-skinned)', 'Crustaceans', 'Molluscs'], correctIndex: 1, explanation: 'Despite the name, starfish are not fish - they are sea echinoderms, cousins of sea urchins.' },
  { id: 485, category: 'Science and Nature', question: 'Jellyfish are best classified as what?', options: ['Fish', 'Cnidarians', 'Molluscs', 'Corals only'], correctIndex: 1, explanation: 'Jellyfish are cnidarians - simple animals with stinging cells, 98% water.' },
  { id: 486, category: 'Science and Nature', question: 'Octopuses belong to which class of animals?', options: ['Cephalopods', 'Crustaceans', 'Echinoderms', 'Annelids'], correctIndex: 0, explanation: 'Cephalopods mean "head feet" - octopuses have their eight arms around their mouth.' },
  { id: 487, category: 'Science and Nature', question: 'Which is the largest animal to have ever lived on Earth?', options: ['Blue whale', 'African elephant', 'Tyrannosaurus rex', 'Colossal squid'], correctIndex: 0, explanation: 'Blue whales reach 30 m and 150+ tonnes - bigger than any dinosaur.' },
  { id: 488, category: 'Science and Nature', question: 'Which bird holds the record for the fastest animal on Earth (in a dive)?', options: ['Peregrine falcon', 'Golden eagle', 'Ostrich', 'Penguin'], correctIndex: 0, explanation: 'Peregrine falcons can stoop at over 300 km/h.' },
  { id: 489, category: 'Science and Nature', question: 'Which is the fastest land animal?', options: ['Pronghorn', 'Cheetah', 'Lion', 'Gazelle'], correctIndex: 1, explanation: 'Cheetahs can hit about 120 km/h in short bursts.' },
  { id: 490, category: 'Science and Nature', question: 'How many hearts does an octopus have?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Two hearts pump blood to the gills; a third pumps it to the body.' },
  { id: 491, category: 'Science and Nature', question: 'Bats are the only mammals that can do what?', options: ['Swim', 'Truly fly', 'See in the dark', 'Live in deserts'], correctIndex: 1, explanation: 'Bats are the only mammals with true powered flight - their wings are stretched skin over finger bones.' },
  { id: 492, category: 'Science and Nature', question: 'The "waggle dance" performed by honeybees communicates what to other bees?', options: ['The direction and distance of food', 'Danger from predators', 'The Queen\'s age', 'The weather'], correctIndex: 0, explanation: 'The angle of the dance relative to the sun tells nestmates where to forage.' },
  { id: 493, category: 'Science and Nature', question: 'A frog\'s life cycle - from egg to tadpole to adult - is an example of what process?', options: ['Metamorphosis', 'Fossilisation', 'Photosynthesis', 'Fermentation'], correctIndex: 0, explanation: 'Metamorphosis is a dramatic change of form between life stages.' },
  { id: 494, category: 'Science and Nature', question: 'Elephants communicate over long distances using what kind of sound?', options: ['Infrasound (below human hearing)', 'Ultrasonic clicks', 'Visible light', 'Chemical trails only'], correctIndex: 0, explanation: 'Low-frequency rumbles can travel several kilometres through the ground.' },
  { id: 495, category: 'Science and Nature', question: 'Which of these animals has blue blood?', options: ['Octopus', 'Shark', 'Dolphin', 'Frog'], correctIndex: 0, explanation: 'Octopus blood uses copper-based haemocyanin, which turns blue when oxygenated.' },
  { id: 496, category: 'Science and Nature', question: 'The monarch butterfly is famous for what remarkable behaviour?', options: ['Long-distance migration', 'Glowing at night', 'Living underwater', 'Freezing for a year'], correctIndex: 0, explanation: 'Monarchs migrate up to 4,000 km between Canada/USA and Mexico each year.' },
  { id: 497, category: 'Science and Nature', question: 'Whales produce songs that can travel for what reason?', options: ['To communicate over long distances', 'To cook food', 'To mark territory with light', 'To clean their skin'], correctIndex: 0, explanation: 'Whale song carries for hundreds of kilometres through ocean water.' },
  { id: 498, category: 'Science and Nature', question: 'Which has the largest brain of any land animal?', options: ['Elephant', 'Dolphin', 'Hippo', 'Gorilla'], correctIndex: 0, explanation: 'Elephant brains weigh about 5 kg - the biggest on land, though dolphins are smarter per gram.' },
  { id: 499, category: 'Science and Nature', question: 'Bees, wasps and ants all belong to which order of insects?', options: ['Hymenoptera', 'Lepidoptera', 'Coleoptera', 'Diptera'], correctIndex: 0, explanation: 'Hymenoptera is the "saw-winged" order, home to bees and wasps.' },
  { id: 500, category: 'Science and Nature', question: 'A cobra is a type of what?', options: ['Serpent with a hood', 'Lizard', 'Seal', 'Crab'], correctIndex: 0, explanation: 'Cobras spread a hood of skin as a warning display.' },
  { id: 501, category: 'Science and Nature', question: 'Which sea creature can regenerate a lost arm?', options: ['Starfish', 'Dolphin', 'Turtle', 'Seahorse'], correctIndex: 0, explanation: 'Starfish can regrow lost arms - and a fragment with part of the central disc can grow into a new starfish.' },
  { id: 502, category: 'Science and Nature', question: 'Chlorophyll, the pigment that makes plants green, is mainly found in which part of a plant?', options: ['Roots', 'Leaves', 'Seeds', 'Bark'], correctIndex: 1, explanation: 'Leaves are the main photosynthesis factory, packed with chlorophyll.' },
  { id: 503, category: 'Science and Nature', question: 'The process by which plants make their own food from sunlight is called what?', options: ['Photosynthesis', 'Respiration', 'Transpiration', 'Fermentation'], correctIndex: 0, explanation: 'Photosynthesis converts CO2, water and light into glucose and oxygen.' },
  { id: 504, category: 'Science and Nature', question: 'Which part of a plant absorbs water and minerals from the soil?', options: ['Leaves', 'Roots', 'Flowers', 'Fruit'], correctIndex: 1, explanation: 'Root hair cells take up water by osmosis.' },
  { id: 505, category: 'Science and Nature', question: 'Xylem and phloem are the plant\'s two main what?', options: ['Transport tissues', 'Root types', 'Flower parts', 'Seed types'], correctIndex: 0, explanation: 'Xylem carries water up; phloem carries sugars around the plant.' },
  { id: 506, category: 'Science and Nature', question: 'Turning toward a light source is called what in plants?', options: ['Phototropism', 'Geotropism', 'Thigmotropism', 'Hydrotropism'], correctIndex: 0, explanation: 'Shoots grow toward light - that is positive phototropism.' },
  { id: 507, category: 'Science and Nature', question: 'A potato, the food we dig up and eat, is botanically what part of the plant?', options: ['A root', 'A stem (tuber)', 'A leaf', 'A fruit'], correctIndex: 1, explanation: 'Potatoes are swollen underground stems - the "eyes" are buds.' },
  { id: 508, category: 'Science and Nature', question: 'An onion is an example of what kind of storage organ?', options: ['A bulb', 'A tuber', 'A rhizome', 'A seed'], correctIndex: 0, explanation: 'Bulbs are short, swollen stems with fleshy leaves storing energy.' },
  { id: 509, category: 'Science and Nature', question: 'Although we cook it as a vegetable, a tomato is botanically what?', options: ['A fruit', 'A root', 'A grain', 'A fungus'], correctIndex: 0, explanation: 'A tomato develops from a flower and contains seeds - the botanical definition of fruit.' },
  { id: 510, category: 'Science and Nature', question: 'Cacti store most of their water in which part?', options: ['Stem', 'Roots', 'Flowers', 'Thorns'], correctIndex: 0, explanation: 'The fleshy stem is the cactus\'s main water tank.' },
  { id: 511, category: 'Science and Nature', question: 'Which tree, famous for storing enormous amounts of water, is known as the "baobab"?', options: ['A African species', 'A New Zealand species', 'A Japanese species', 'A Scottish species'], correctIndex: 0, explanation: 'Baobabs of Africa can hold up to 120,000 litres of water in their trunks.' },
  { id: 512, category: 'Science and Nature', question: 'Pine trees, which keep their leaves year-round, are called what?', options: ['Evergreens (conifers)', 'Deciduous', 'Flowering', 'Ferns'], correctIndex: 0, explanation: 'Conifers produce cones and retain needle-like leaves.' },
  { id: 513, category: 'Science and Nature', question: 'Coral, which builds the great reefs, is actually what kind of organism?', options: ['An animal', 'A plant', 'A rock', 'A fungus'], correctIndex: 0, explanation: 'Coral reefs are built by colonies of tiny animals called coral polyps.' },
  { id: 514, category: 'Science and Nature', question: 'Seaweed is best classified as what?', options: ['An alga (not a true plant)', 'A grass', 'A fungus', 'A vegetable'], correctIndex: 0, explanation: 'Seaweeds are algae - they photosynthesise but lack true plant roots and flowers.' },
  { id: 515, category: 'Science and Nature', question: 'The giant redwood trees, among the tallest on Earth, are native to which region?', options: ['Coastal California', 'The Amazon', 'New Zealand', 'Norway'], correctIndex: 0, explanation: 'Coastal redwoods can exceed 115 m in tall, foggy California.' },
  { id: 516, category: 'Science and Nature', question: 'The rubber latex used to make tyres is tapped from which tree?', options: ['Rubber tree (Hevea)', 'Oak', 'Palm', 'Cocoa'], correctIndex: 0, explanation: 'Latex is collected by making diagonal cuts in the bark of Hevea brasiliensis.' },
  { id: 517, category: 'Science and Nature', question: 'Water is a compound of which two elements?', options: ['Hydrogen and oxygen', 'Hydrogen and carbon', 'Oxygen and carbon', 'Nitrogen and oxygen'], correctIndex: 0, explanation: 'Each water molecule is H2O - two hydrogen, one oxygen.' },
  { id: 518, category: 'Science and Nature', question: 'The gas that animals breathe out, CO2, is made of carbon and what?', options: ['Oxygen', 'Hydrogen', 'Nitrogen', 'Helium'], correctIndex: 0, explanation: 'CO2 is one carbon atom double-bonded to two oxygen atoms.' },
  { id: 519, category: 'Science and Nature', question: 'Methane, the main component of natural gas, has the formula what?', options: ['CH4', 'CO2', 'C2H6', 'H2O'], correctIndex: 0, explanation: 'Methane is one carbon with four hydrogens - a potent greenhouse gas.' },
  { id: 520, category: 'Science and Nature', question: 'The pH scale measures what property of a solution?', options: ['Acidity or alkalinity', 'Temperature', 'Density', 'Salinity'], correctIndex: 0, explanation: 'pH 7 is neutral; below is acidic, above is alkaline.' },
  { id: 521, category: 'Science and Nature', question: 'The pH of pure water is what?', options: ['7', '0', '14', '1'], correctIndex: 0, explanation: 'Pure water is neutral, at pH 7.' },
  { id: 522, category: 'Science and Nature', question: 'Which common kitchen substance is a weak acid found in lemons?', options: ['Citric acid', 'Acetic acid', 'Lactic acid', 'Oxalic acid'], correctIndex: 0, explanation: 'Citric acid gives citrus fruits their sharp tang.' },
  { id: 523, category: 'Science and Nature', question: 'Baking soda, used in cooking, is the common name for what compound?', options: ['Sodium bicarbonate', 'Sodium chloride', 'Calcium carbonate', 'Potassium nitrate'], correctIndex: 0, explanation: 'Sodium bicarbonate (NaHCO3) fizzes when it meets acid and heat.' },
  { id: 524, category: 'Science and Nature', question: 'Rust, the reddish coating on old iron, is a form of what?', options: ['Iron oxide', 'Iron sulfate', 'Iron carbide', 'Iron fluoride'], correctIndex: 0, explanation: 'Iron reacts with oxygen and water to form hydrated iron oxide - rust.' },
  { id: 525, category: 'Science and Nature', question: 'Diamond and pencil graphite are both made of which single element?', options: ['Carbon', 'Silicon', 'Calcium', 'Sulfur'], correctIndex: 0, explanation: 'Same atom, different arrangement: diamond is a hard lattice, graphite is soft layers.' },
  { id: 526, category: 'Science and Nature', question: 'Which noble gas, used in bright red signs, does not readily react with other elements?', options: ['Neon', 'Oxygen', 'Hydrogen', 'Nitrogen'], correctIndex: 0, explanation: 'Neon\'s full outer shell makes it chemically inert; it glows red-orange when electrified.' },
  { id: 527, category: 'Science and Nature', question: 'Which element, found in blood, gives it its red colour?', options: ['Iron', 'Copper', 'Sodium', 'Zinc'], correctIndex: 0, explanation: 'Iron in haemoglobin binds oxygen and turns red.' },
  { id: 528, category: 'Science and Nature', question: 'Which light, silvery metal is widely used in electrical wiring because it conducts well?', options: ['Copper', 'Lead', 'Tin', 'Zinc'], correctIndex: 0, explanation: 'Copper\'s excellent conductivity makes it the standard wiring metal.' },
  { id: 529, category: 'Science and Nature', question: 'Which is the most abundant metal in the Earth\'s crust?', options: ['Aluminium', 'Iron', 'Copper', 'Zinc'], correctIndex: 0, explanation: 'Aluminium makes up about 8% of the crust - more than any other metal.' },
  { id: 530, category: 'Science and Nature', question: 'Which metal is so soft it can be cut with a knife and is stored under oil?', options: ['Sodium', 'Iron', 'Copper', 'Nickel'], correctIndex: 0, explanation: 'Sodium is reactive and greasy-soft; it fizzes violently in water.' },
  { id: 531, category: 'Science and Nature', question: 'Which element is used to make strong, lightweight aircraft parts and is named after a Swedish mineral?', options: ['Titanium', 'Aluminium', 'Magnesium', 'Lithium'], correctIndex: 0, explanation: 'Titanium is as strong as steel but much lighter - a favourite of engineers.' },
  { id: 532, category: 'Science and Nature', question: 'The light metals in rechargeable phone batteries are often based on which element?', options: ['Lithium', 'Lead', 'Zinc', 'Tin'], correctIndex: 0, explanation: 'Lithium-ion batteries store energy in lithium compounds - light and high capacity.' },
  { id: 533, category: 'Science and Nature', question: 'Uranium, used in nuclear power stations, is an example of what kind of element?', options: ['Radioactive', 'Inert', 'Alkaline', 'A noble gas'], correctIndex: 0, explanation: 'Uranium\'s unstable nucleus decays, releasing energy and radiation.' },
  { id: 534, category: 'Science and Nature', question: 'Which gas, lighter than air, is pumped into party balloons?', options: ['Helium', 'Hydrogen', 'Carbon dioxide', 'Oxygen'], correctIndex: 0, explanation: 'Helium is a safe inert gas lighter than air, so balloons rise.' },
  { id: 535, category: 'Science and Nature', question: 'Table sugar (sucrose) is a compound of carbon, hydrogen and what?', options: ['Oxygen', 'Nitrogen', 'Sulfur', 'Calcium'], correctIndex: 0, explanation: 'Sucrose is C12H22O11 - carbon, hydrogen and oxygen.' },
  { id: 536, category: 'Science and Nature', question: 'Ozone, the protective layer high above Earth, is a form of what element?', options: ['Oxygen (O3)', 'Ozone is its own element', 'Nitrogen', 'Carbon'], correctIndex: 0, explanation: 'Ozone is three oxygen atoms bonded together - O3.' },
  { id: 537, category: 'Science and Nature', question: 'The force that pulls objects toward the centre of the Earth is called what?', options: ['Gravity', 'Magnetism', 'Friction', 'Tension'], correctIndex: 0, explanation: 'Gravity is the attraction between any two masses.' },
  { id: 538, category: 'Science and Nature', question: 'The force that opposes motion when two surfaces rub together is what?', options: ['Friction', 'Gravity', 'Magnetism', 'Buoyancy'], correctIndex: 0, explanation: 'Friction converts motion into heat - rub your hands together to feel it.' },
  { id: 539, category: 'Science and Nature', question: 'A magnet always has which two poles?', options: ['North and south', 'Positive and negative', 'Hot and cold', 'Inner and outer'], correctIndex: 0, explanation: 'Like poles repel, opposite poles attract.' },
  { id: 540, category: 'Science and Nature', question: 'The three common states of matter are solid, liquid and what?', options: ['Gas', 'Plasma only', 'Energy', 'Vacuum'], correctIndex: 0, explanation: 'Solids, liquids and gases are the everyday states; plasma is a fourth, found in stars.' },
  { id: 541, category: 'Science and Nature', question: 'When a solid turns into a liquid, the process is called what?', options: ['Melting', 'Freezing', 'Condensing', 'Subliming'], correctIndex: 0, explanation: 'Melting happens when a solid gains enough energy to break its rigid structure.' },
  { id: 542, category: 'Science and Nature', question: 'Dry ice, solid carbon dioxide, changes straight from solid to gas. This is called what?', options: ['Sublimation', 'Evaporation', 'Condensation', 'Freezing'], correctIndex: 0, explanation: 'Sublimation skips the liquid stage entirely - which is why dry ice fizzes.' },
  { id: 543, category: 'Science and Nature', question: 'The SI unit of energy is what?', options: ['Joule', 'Watt', 'Newton', 'Volt'], correctIndex: 0, explanation: 'A joule is the energy needed to move 1 newton over 1 metre.' },
  { id: 544, category: 'Science and Nature', question: 'The SI unit of force is what?', options: ['Newton', 'Joule', 'Pascal', 'Ampere'], correctIndex: 0, explanation: 'Forces are measured in newtons, named after Isaac Newton.' },
  { id: 545, category: 'Science and Nature', question: 'The SI unit of electrical power is what?', options: ['Watt', 'Volt', 'Ampere', 'Ohm'], correctIndex: 0, explanation: 'One watt equals one joule of energy per second.' },
  { id: 546, category: 'Science and Nature', question: 'Isaac Newton\'s second law of motion is famously written as what?', options: ['F = ma', 'E = mc2', 'V = IR', 'PV = nRT'], correctIndex: 0, explanation: 'Force equals mass times acceleration.' },
  { id: 547, category: 'Science and Nature', question: 'The principle that a submerged object is buoyed up by a force equal to the weight of fluid it displaces is called what?', options: ['Archimedes\' principle', 'Pascal\'s law', 'Boyle\'s law', 'Ohm\'s law'], correctIndex: 0, explanation: 'Archimedes discovered it (allegedly in a bath) - it is why ships float.' },
  { id: 548, category: 'Science and Nature', question: 'A material that allows electricity to flow easily, like copper, is called what?', options: ['A conductor', 'An insulator', 'A resistor', 'A semiconductor'], correctIndex: 0, explanation: 'Metals conduct because their electrons are free to move.' },
  { id: 549, category: 'Science and Nature', question: 'The unit of electrical voltage is what?', options: ['Volt', 'Ampere', 'Ohm', 'Watt'], correctIndex: 0, explanation: 'Volts measure the electrical "push" that drives current.' },
  { id: 550, category: 'Science and Nature', question: 'A lever, a pulley and a wheel-and-axle are all examples of what?', options: ['Simple machines', 'Living things', 'Energy sources', 'Rockets'], correctIndex: 0, explanation: 'Simple machines make work easier by trading force for distance.' },
  { id: 551, category: 'Science and Nature', question: 'Sound travels fastest through which type of material?', options: ['Solids', 'Liquids', 'Gases', 'A vacuum'], correctIndex: 0, explanation: 'Tightly packed solid particles pass vibrations along quicker than spread-out gas particles.' },
  { id: 552, category: 'Science and Nature', question: 'The human ear can typically hear sounds between 20 Hz and about 20,000 Hz. This range is called what?', options: ['The audible range', 'The infrared range', 'The ultraviolet range', 'The gamma range'], correctIndex: 0, explanation: 'Below 20 Hz is infrasound (elephants), above is ultrasound (bats, medical scans).' },
  { id: 553, category: 'Science and Nature', question: 'The "pitch" of a sound is determined mainly by what?', options: ['Frequency', 'Amplitude', 'Volume only', 'The colour of the source'], correctIndex: 0, explanation: 'Higher frequency means higher pitch - amplitude controls loudness.' },
  { id: 554, category: 'Science and Nature', question: 'White light passed through a prism splits into a rainbow because of what process?', options: ['Refraction', 'Reflection only', 'Absorption only', 'Diffusion'], correctIndex: 0, explanation: 'Different colours bend by different amounts in glass, separating the spectrum.' },
  { id: 555, category: 'Science and Nature', question: 'In a rainbow, which colour is bent the most and sits at the bottom of the arc?', options: ['Violet', 'Red', 'Green', 'Yellow'], correctIndex: 0, explanation: 'Violet bends most; red bends least and tops the rainbow.' },
  { id: 556, category: 'Science and Nature', question: 'Which colour is at the top of a rainbow?', options: ['Red', 'Violet', 'Blue', 'Orange'], correctIndex: 0, explanation: 'Red is deflected the least, so it appears on the outer (top) edge.' },
  { id: 557, category: 'Science and Nature', question: 'The Sun, at the centre of our solar system, is best described as what?', options: ['A star', 'A planet', 'A comet', 'A galaxy'], correctIndex: 0, explanation: 'The Sun is a medium-sized star - a giant ball of fusing hydrogen.' },
  { id: 558, category: 'Science and Nature', question: 'The point on the Earth\'s surface directly above where an earthquake starts is called what?', options: ['Epicentre', 'Focus', 'Fault line', 'Ridge'], correctIndex: 0, explanation: 'The focus is the underground origin; the epicentre is directly above it at the surface.' },
  { id: 559, category: 'Science and Nature', question: 'The giant, mostly underwater mountain belt around the Pacific Ocean is called what?', options: ['The Ring of Fire', 'The Mid-Atlantic Ridge', 'The Himalayas', 'The Great Rift'], correctIndex: 0, explanation: 'The Ring of Fire hosts about 75% of the world\'s active volcanoes.' },
  { id: 560, category: 'Science and Nature', question: 'Molten rock that erupts from a volcano and flows on the surface is called what?', options: ['Lava', 'Magma', 'Gneiss', 'Pumice'], correctIndex: 0, explanation: 'Underground it is magma; once it erupts it is lava.' },
  { id: 561, category: 'Science and Nature', question: 'Which of the three main rock types forms from cooled and solidified molten rock?', options: ['Igneous', 'Sedimentary', 'Metamorphic', 'Organic'], correctIndex: 0, explanation: 'Igneous rocks, like granite and basalt, crystallise from magma or lava.' },
  { id: 562, category: 'Science and Nature', question: 'Rock formed from compacted layers of sand, silt or shells is what type?', options: ['Sedimentary', 'Igneous', 'Metamorphic', 'Volcanic'], correctIndex: 0, explanation: 'Sedimentary rocks like sandstone build up in layers over millions of years.' },
  { id: 563, category: 'Science and Nature', question: 'Marble, a fine stone used in sculpture, forms from limestone under heat and pressure. It is what type of rock?', options: ['Metamorphic', 'Igneous', 'Sedimentary', 'Organic'], correctIndex: 0, explanation: 'Metamorphic rocks are transformed by intense heat and pressure.' },
  { id: 564, category: 'Science and Nature', question: 'The continuous, global system of Earth\'s moving tectonic plates is studied in what field?', options: ['Plate tectonics', 'Meteorology', 'Botany', 'Astronomy'], correctIndex: 0, explanation: 'Plate tectonics explains earthquakes, volcanoes and mountain building.' },
  { id: 565, category: 'Science and Nature', question: 'New ocean crust is created where tectonic plates pull apart, in a process called what?', options: ['Seafloor spreading', 'Subduction', 'Folding', 'Erosion'], correctIndex: 0, explanation: 'Magma rises at mid-ocean ridges to form new seafloor, pushing plates apart.' },
  { id: 566, category: 'Science and Nature', question: 'Tides, the daily rise and fall of sea level, are mainly caused by the gravity of what?', options: ['The Moon', 'The Sun only', 'The wind', 'Earth\'s rotation only'], correctIndex: 0, explanation: 'The Moon\'s gravity bulges the oceans; the Sun adds a smaller effect.' },
  { id: 567, category: 'Science and Nature', question: 'Seawater is salty mainly because rivers carry dissolved what from eroded rock into the oceans?', options: ['Minerals (salts)', 'Plastic', 'Oil', 'Sugar'], correctIndex: 0, explanation: 'Over billions of years, dissolved minerals have concentrated in the oceans.' },
  { id: 568, category: 'Science and Nature', question: 'The slow, global circulation of deep ocean currents, driven by temperature and salt, is known as what?', options: ['The thermohaline circulation', 'The jet stream', 'The Hadley cell', 'The Coriolis effect'], correctIndex: 0, explanation: 'This "global conveyor belt" can take a water parcel centuries to complete a loop.' },
  { id: 569, category: 'Science and Nature', question: 'Renewable energy sources include all of the following except what?', options: ['Coal', 'Solar', 'Wind', 'Hydro'], correctIndex: 0, explanation: 'Coal is a finite fossil fuel; solar, wind and water are renewable.' },
  { id: 570, category: 'Science and Nature', question: 'Nuclear power stations release energy by splitting heavy atoms in a process called what?', options: ['Fission', 'Fusion', 'Combustion', 'Oxidation'], correctIndex: 0, explanation: 'Fission splits uranium atoms; fusion (which powers the Sun) joins light ones.' },
  { id: 571, category: 'Science and Nature', question: 'The main greenhouse gas released by burning fossil fuels is what?', options: ['Carbon dioxide', 'Oxygen', 'Helium', 'Argon'], correctIndex: 0, explanation: 'CO2 from fossil fuels is the largest driver of recent global warming.' },
  { id: 572, category: 'Science and Nature', question: 'Acid rain is mainly caused by which pollutant reacting in the atmosphere?', options: ['Sulfur dioxide', 'Oxygen', 'Nitrogen gas', 'Argon'], correctIndex: 0, explanation: 'Sulfur dioxide from burning coal forms sulfuric acid in rain clouds.' },
  { id: 573, category: 'Science and Nature', question: 'Methane, a potent greenhouse gas, is released in large amounts from which human activity?', options: ['Rice farming and cattle', 'Solar panels', 'Wind turbines', 'Hydropower'], correctIndex: 0, explanation: 'Rice paddies and cattle digestion are major methane sources.' },
  { id: 574, category: 'Science and Nature', question: 'Geothermal energy, tapped from wells in places like Iceland, comes from what?', options: ['Heat from Earth\'s interior', 'The Sun', 'The wind', 'Tides'], correctIndex: 0, explanation: 'Radioactive decay and residual formation heat warm underground water and rock.' },
  { id: 575, category: 'Science and Nature', question: 'A tsunami, a series of huge ocean waves, is most often triggered by what?', options: ['An undersea earthquake', 'A strong wind', 'A passing ship', 'A volcano erupting on land'], correctIndex: 0, explanation: 'Quakes that vertically displace the seafloor launch tsunami waves.' },
  { id: 576, category: 'Science and Nature', question: 'The Apollo 13 mission, in 1970, is famous for what?', options: ['A successful return after a catastrophic failure', 'First woman on the Moon', 'First dog in space', 'Building the first base'], correctIndex: 0, explanation: '"Houston, we\'ve had a problem" - an oxygen tank explosion, and a brilliant rescue.' },
  { id: 577, category: 'Science and Nature', question: 'Which is the farthest human-made object from Earth?', options: ['Voyager 1', 'Hubble', 'ISS', 'James Webb'], correctIndex: 0, explanation: 'Launched in 1977, Voyager 1 is over 24 billion km away in interstellar space.' },
  { id: 578, category: 'Science and Nature', question: 'The Hubble Space Telescope, launched in 1990, orbits where?', options: ['In low Earth orbit', 'Around the Moon', 'At the Sun', 'On a satellite of Saturn'], correctIndex: 0, explanation: 'Hubble circles Earth about every 95 minutes, above most of the atmosphere.' },
  { id: 579, category: 'Science and Nature', question: 'About 99.8% of the mass of our solar system is contained in what?', options: ['The Sun', 'Jupiter', 'The asteroids', 'All the planets combined'], correctIndex: 0, explanation: 'The Sun is overwhelmingly the solar system\'s mass; Jupiter has most of the rest.' },
  { id: 580, category: 'Science and Nature', question: 'Ganymede, the largest moon in the solar system, orbits which planet?', options: ['Jupiter', 'Saturn', 'Mars', 'Neptune'], correctIndex: 0, explanation: 'Ganymede is bigger than the planet Mercury - it is the largest moon of Jupiter.' },
  { id: 581, category: 'Science and Nature', question: 'The International Space Station, a continuously inhabited space laboratory, orbits about how high above Earth?', options: ['About 400 km', '4,000 km', '40 km', 'At the Moon'], correctIndex: 0, explanation: 'The ISS circles Earth every 90 minutes at roughly 400 km altitude.' },
  { id: 582, category: 'Science and Nature', question: 'Radar, used in weather forecasting and speed guns, works by bouncing off objects what?', options: ['Radio waves', 'Sound waves', 'X-rays', 'Gamma rays'], correctIndex: 0, explanation: 'RADAR means RA Dio And Ranging - it measures the echo of radio waves.' },
  { id: 583, category: 'Science and Nature', question: 'Ultrasound imaging, used to scan unborn babies, uses what kind of waves?', options: ['Sound waves above human hearing', 'Light waves', 'Radio waves', 'Water waves'], correctIndex: 0, explanation: 'Ultrasound bounces off tissue boundaries; the echoes form the image.' },
  { id: 584, category: 'Science and Nature', question: 'A battery produces electricity through what kind of reaction?', options: ['A chemical reaction', 'A nuclear reaction', 'A gravitational reaction', 'A magnetic reaction'], correctIndex: 0, explanation: 'Chemical energy in a battery is converted to electrical energy.' },
  { id: 585, category: 'Science and Nature', question: 'A chemical reaction in which a substance combines with oxygen and releases heat is called what?', options: ['Combustion', 'Fermentation', 'Osmosis', 'Sublimation'], correctIndex: 0, explanation: 'Burning is combustion - fuel plus oxygen gives heat, light and new compounds.' },
  { id: 586, category: 'Science and Nature', question: 'The process by which sugars break down without oxygen to release energy is called what?', options: ['Fermentation', 'Photosynthesis', 'Oxidation', 'Condensation'], correctIndex: 0, explanation: 'Yeast ferment sugar into alcohol and CO2 - that is how bread rises and beer brews.' },
  { id: 587, category: 'Science and Nature', question: 'Vinegar, a common kitchen liquid, contains which weak acid?', options: ['Acetic acid', 'Citric acid', 'Sulfuric acid', 'Lactic acid'], correctIndex: 0, explanation: 'Acetic acid gives vinegar its sharp sour taste.' },
  { id: 588, category: 'Science and Nature', question: 'When an acid and a base react to form salt and water, the process is called what?', options: ['Neutralisation', 'Oxidation', 'Fermentation', 'Distillation'], correctIndex: 0, explanation: 'Neutralisation brings the pH back toward 7.' },
  { id: 589, category: 'Science and Nature', question: 'Iron left outside in rain slowly rusts. Rusting is an example of what kind of change?', options: ['A chemical change', 'A physical change only', 'A nuclear change', 'No change'], correctIndex: 0, explanation: 'Rusting creates a new substance (iron oxide) - a chemical change.' },
  { id: 590, category: 'Science and Nature', question: 'Mixing sugar into water until it dissolves is an example of what kind of change?', options: ['A physical change', 'A chemical change', 'A nuclear change', 'A biological change'], correctIndex: 0, explanation: 'Dissolving can be reversed by evaporating the water - no new substance forms.' },
  { id: 591, category: 'Science and Nature', question: 'An acid turns blue litmus paper what colour?', options: ['Red', 'Blue', 'Green', 'Yellow'], correctIndex: 0, explanation: 'Acids turn blue litmus red; bases turn red litmus blue.' },
  { id: 592, category: 'Science and Nature', question: 'When light bounces off a smooth surface, such as a mirror, the process is called what?', options: ['Reflection', 'Refraction', 'Diffraction', 'Dispersion'], correctIndex: 0, explanation: 'Reflection follows the rule that the angle of incidence equals the angle of reflection.' },
  { id: 593, category: 'Science and Nature', question: 'When water vapour in the air cools and turns back into liquid droplets, it is called what?', options: ['Condensation', 'Evaporation', 'Sublimation', 'Freezing'], correctIndex: 0, explanation: 'Condensation forms clouds, dew and the mist on a cold glass.' },
  { id: 594, category: 'Science and Nature', question: 'Plants release which gas into the air during photosynthesis?', options: ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Helium'], correctIndex: 0, explanation: 'Oxygen is a by-product of photosynthesis - the breath of most life on Earth.' },
  { id: 595, category: 'Science and Nature', question: 'Seeds need light, warmth and what else to germinate?', options: ['Moisture', 'Salt', 'Acid', 'Air pressure'], correctIndex: 0, explanation: 'Water, warmth and (for many seeds) light trigger the seed to sprout.' },
  { id: 596, category: 'Science and Nature', question: 'The tiny openings on the underside of leaves that let gas in and out are called what?', options: ['Stomata', 'Chloroplasts', 'Xylem', 'Pores only'], correctIndex: 0, explanation: 'Stomata open and close to balance gas exchange with water loss.' },
  { id: 597, category: 'Science and Nature', question: 'Fungi, such as mushrooms and mould, are neither plants nor animals. They obtain nutrients mainly by what?', options: ['Absorbing them from other organisms', 'Photosynthesis', 'Hunting prey', 'Drinking salt water'], correctIndex: 0, explanation: 'Fungi are decomposers - they secrete enzymes and absorb the dissolved nutrients.' },
  { id: 598, category: 'Science and Nature', question: 'A mushroom is the fruiting body of what kind of organism?', options: ['A fungus', 'A plant', 'A lichen only', 'An algae'], correctIndex: 0, explanation: 'Most of a fungus lives hidden underground as thread-like hyphae.' },
  { id: 599, category: 'Science and Nature', question: 'Vaccines protect the body by training which part of the immune system?', options: ['Antibodies and memory cells', 'Red blood cells', 'The stomach', 'The skin'], correctIndex: 0, explanation: 'A vaccine shows the immune system a harmless version of a pathogen to remember.' },
  { id: 600, category: 'Science and Nature', question: 'Penicillin, discovered by Alexander Fleming in 1928, is a type of what?', options: ['Antibiotic', 'Vaccine', 'Vitamin', 'Hormone'], correctIndex: 0, explanation: 'Penicillin kills bacteria by disrupting their cell walls - Fleming found it via a mouldy plate.' },
  { id: 601, category: 'Science and Nature', question: 'Viruses, which cause colds and flu, are best described as what?', options: ['Very small infectious agents that need a host cell to replicate', 'Tiny plants', 'Bacteria with tails', 'Minerals'], correctIndex: 0, explanation: 'Viruses are not fully "alive" - they hijack host cells to copy themselves.' },
  { id: 602, category: 'Science and Nature', question: 'An ecosystem consists of all the living things in an area plus what?', options: ['Their non-living environment', 'Only the plants', 'Only the animals', 'The atmosphere only'], correctIndex: 0, explanation: 'Ecosystems pair living (biotic) with non-living (abiotic) parts.' },
  { id: 603, category: 'Science and Nature', question: 'In a food chain, plants, which make their own food, are called what?', options: ['Producers', 'Consumers', 'Decomposers', 'Predators'], correctIndex: 0, explanation: 'Producers (usually plants) start every food chain by fixing sunlight.' },
  { id: 604, category: 'Science and Nature', question: 'The red panda, with its ringed tail, is actually what kind of animal?', options: ['A mammal', 'A bird', 'A reptile', 'A red fox'], correctIndex: 0, explanation: 'The red panda is a small mammal related to raccoons, not to the giant panda (a bear).' },
  { id: 605, category: 'Science and Nature', question: 'A dolphin, despite living in the sea, is classified as what?', options: ['A mammal', 'A fish', 'A reptile', 'A crustacean'], correctIndex: 0, explanation: 'Dolphins breathe air, are warm-blooded and feed their young milk - mammals.' },
  { id: 606, category: 'Science and Nature', question: 'Sharks, unlike most fish, have skeletons made of what?', options: ['Cartilage', 'Bone', 'Wood', 'Calcium carbonate'], correctIndex: 0, explanation: 'Sharks are cartilaginous fish - light and flexible, with no true bone.' },
  { id: 607, category: 'Science and Nature', question: 'Which unusual fish is the male that carries and gives birth to the young?', options: ['Seahorse', 'Goldfish', 'Shark', 'Pufferfish'], correctIndex: 0, explanation: 'Male seahorses brood the eggs in a pouch and give birth to the fry.' },
  { id: 608, category: 'Science and Nature', question: 'The axolotl, a mexican salamander, is famous for its ability to do what?', options: ['Regenerate lost limbs', 'Fly', 'Live on land only', 'Photosynthesise'], correctIndex: 0, explanation: 'Axolotls can regrow limbs, spinal cord and even part of their heart.' },
  { id: 609, category: 'Science and Nature', question: 'The narwhal, the "unicorn of the sea", is a whale with what distinctive feature?', options: ['A long spiral tusk', 'Horns on its head', 'A blue tail', 'A long beak'], correctIndex: 0, explanation: 'The tusk is actually an oversized tooth, usually grown by males.' },
  { id: 610, category: 'Science and Nature', question: 'Koalas, often mistaken for bears, are native to which country?', options: ['Australia', 'New Zealand', 'South Africa', 'Brazil'], correctIndex: 0, explanation: 'Koalas are marsupials - mothers carry their young in a pouch.' },
  { id: 611, category: 'Science and Nature', question: 'A baby cow is called what?', options: ['A calf', 'A puppy', 'A kit', 'A foal'], correctIndex: 0, explanation: 'Calves - from the Old English for "young of any animal" - are baby cows.' },
  { id: 612, category: 'Science and Nature', question: 'Which bird is well known for using tools and solving puzzles?', options: ['Crow', 'Sparrow', 'Pigeon', 'Duck'], correctIndex: 0, explanation: 'Crows bend wire into hooks and plan multi-step solutions - among the cleverest animals.' },
  { id: 613, category: 'Science and Nature', question: 'How many legs does a spider have?', options: ['Eight', 'Six', 'Ten', 'Four'], correctIndex: 0, explanation: 'Spiders are arachnids with eight legs - insects have six.' },
  { id: 614, category: 'Science and Nature', question: 'A ladybird (ladybug) is a predator of which garden pest?', options: ['Aphids', 'Weeds', 'Slugs only', 'Ants'], correctIndex: 0, explanation: 'A single ladybird can eat thousands of aphids in its life - a gardener\'s friend.' },
  { id: 615, category: 'Science and Nature', question: 'Octopuses, the clever cephalopods, have their "brains" mainly where?', options: ['In their arms as well as their head', 'Only in their head', 'In their stomach', 'They have no brain'], correctIndex: 0, explanation: 'Two thirds of an octopus\'s neurons are in its arms - they think with their hands.' },
  { id: 616, category: 'Science and Nature', question: 'Penguins are birds that cannot fly but are expert at what?', options: ['Swimming', 'Climbing trees', 'Burrowing', 'Gliding'], correctIndex: 0, explanation: 'Penguin "wings" are flippers - perfect underwater wings for swimming.' },
  { id: 617, category: 'Science and Nature', question: 'The honey badger, known for its fearlessness, belongs to which family of animals?', options: ['Mustelids (weasel family)', 'Big cats', 'Bears', 'Raccoons'], correctIndex: 0, explanation: 'The honey badger (ratel) is a mustelid - a cousin of the wolverine and otter.' },
  { id: 618, category: 'Science and Nature', question: 'Roughly how many planets are in our solar system (since Pluto\'s 2006 reclassification)?', options: ['Eight', 'Nine', 'Ten', 'Seven'], correctIndex: 0, explanation: 'Eight planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.' },
  { id: 619, category: 'Science and Nature', question: 'The Great Red Spot, a giant storm bigger than Earth, is on which planet?', options: ['Jupiter', 'Saturn', 'Mars', 'Neptune'], correctIndex: 0, explanation: 'The Great Red Spot has been raging on Jupiter for centuries.' },
  { id: 620, category: 'Science and Nature', question: 'About how long does it take Venus to orbit the Sun once?', options: ['225 Earth days', '365 Earth days', '88 Earth days', '687 Earth days'], correctIndex: 0, explanation: 'Venus takes 225 Earth days to orbit the Sun - its year is longer than its 243-day day!' },
  { id: 621, category: 'Science and Nature', question: 'The Northern and Southern Lights (auroras) are caused by what?', options: ['Solar wind particles interacting with Earth\'s magnetic field', 'Lightning in space', 'Reflection of the Moon', 'Volcanic gases'], correctIndex: 0, explanation: 'Charged solar particles glow as they funnel into the polar atmosphere.' },
  { id: 622, category: 'Science and Nature', question: 'Which travels faster: light or sound?', options: ['Light', 'Sound', 'They are the same', 'It depends on the colour'], correctIndex: 0, explanation: 'Light travels ~300,000 km/s; sound in air is a mere ~343 m/s - which is why we see lightning before we hear thunder.' },
];
